        phrases: [['der Blazer', 'the blazer'], ['das T-Shirt', 'the T-shirt'], ['nicht zu formell', 'not too formal'], ['die Beratung', 'the advice']],
        steps: [
          ['frank', 'Hallo! Ich habe nächste Woche ein Vorstellungsgespräch und brauche ein Outfit. Aber nicht zu formell.', 'Hello! I have a job interview next week and need an outfit. But not too formal.'],
          { choose: true, prompt: 'Suggest a blazer with a white T-shirt.', o: ['Wie wäre es mit einem Blazer und einem weißen T-Shirt?', 'Wie wäre es mit ein Blazer und ein weißes T-Shirt?', 'Wie wäre es mit einem Blazer und einem weiße T-Shirt?'], a: 0, ex: '„mit“ always takes the dative: einem Blazer, einem weißen T-Shirt.' },
          ['frank', 'Hm, gute Idee. Welche Farbe würden Sie nehmen?', 'Hm, good idea. Which colour would you take?'],
          ['alex', 'Dunkelblau ist klassisch, aber Beige ist gerade sehr im Trend.', 'Dark blue is classic, but beige is very trendy right now.'],
          ['_', 'Frau Frank probiert einen beigen Blazer an.', 'Ms Frank tries on a beige blazer.'],
          { choose: true, prompt: 'Tell her the blazer suits her very well.', o: ['Der Blazer steht Ihnen sehr gut!', 'Der Blazer steht Sie sehr gut!', 'Der Blazer stehen Ihnen sehr gut!'], a: 0, ex: '„stehen“ (= to suit) takes the dative: Ihnen. One blazer → steht.' },
          ['frank', 'Wirklich? Und welche Hose passt dazu?', 'Really? And which trousers go with it?'],
          ['alex', 'Dazu passt eine gerade schwarze Hose. Und mit Sneakern sieht es modern aus.', 'Straight black trousers go with it. And with sneakers it looks modern.'],
          ['frank', 'Perfekt, so mache ich das. Vielen Dank für die Beratung!', 'Perfect, that’s what I’ll do. Thank you very much for the advice!'],
        ],
